def own_questions(apps, schema_editor):
    """Every question is the coach's own now (Probid 2026-10-31): weekly forms that asked the automatic
    "Body measurements" step get it as a real question before the photos, and the note question keeps its chips."""
    Form = apps.get_model("checkins", "Form")
    Question = apps.get_model("checkins", "Question")
    for f in Form.objects.filter(type="weekly"):
        qs = list(Question.objects.filter(form=f, is_removed=False).order_by("order", "id"))
        if any(q.type == "measures" or q.metric in MEASURE_KEYS for q in qs):
            continue
        at = next((i for i, q in enumerate(qs) if q.type == "photo"), len(qs))
